import SwiftUI
import AppKit

/// Brand colors from the shared OKM palette (OKMPalette.swift, generated by okm-brand; do not hard-code hex here).
enum SKIRRBrand {
    static let navy = Color(nsColor: OKMPalette.brandNavy)
    static let secondary = Color(nsColor: OKMPalette.brandSlate)
    static let accent = Color(nsColor: OKMPalette.accent)
    static let success = Color(nsColor: OKMPalette.success)
    static let warning = Color(nsColor: OKMPalette.warning)
    static let danger = Color(nsColor: OKMPalette.danger)
    /// "OKM" in the wordmark: navy in light mode, white in dark mode (same as OKM Mimir).
    static let wordmark = Color(nsColor: NSColor(name: "OKMWordmarkPrimary") { appearance in
        appearance.bestMatch(from: [.aqua, .darkAqua]) == .darkAqua ? .white : OKMPalette.brandNavy
    })
}

struct SKIRRHeader: View {
    let animate: Bool
    let version: String
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var body: some View {
        VStack(spacing: 14) {
            ZStack {
                Image("SKIRRLogo").resizable().scaledToFit()
                if animate && !reduceMotion && !isSnapshot,
                   let url = Bundle.main.url(forResource: "SKIRR_Logo_animated_v5", withExtension: "svg"),
                   let svg = try? String(contentsOf: url, encoding: .utf8) {
                    SKIRRLogoAnimation(svg: svg)
                }
            }
            .frame(width: 112, height: 112).clipShape(.circle)
            .accessibilityHidden(true)
            HStack(spacing: 12) {
                Text("OKM").foregroundStyle(SKIRRBrand.wordmark)
                Text("SKÍRR").foregroundStyle(SKIRRBrand.secondary)
            }.font(.system(size: 25, weight: .semibold)).tracking(4)
                .accessibilityElement(children: .ignore).accessibilityLabel("OKM SKÍRR")
            Text("版本 \(version)").font(.callout).foregroundStyle(.secondary)
            Text("Copyright © 2026 OKMaster Inc.").font(.caption).foregroundStyle(.secondary)
        }
        .frame(maxWidth: .infinity).padding(.vertical, 26)
        .background(Color.primary.opacity(0.045), in: .rect(cornerRadius: 22))
    }
}

/// Share the chosen appearance between settings, onboarding, and the popover.
struct SKIRRTheme: ViewModifier {
    @AppStorage("skirr.appearance") private var appearance = "system"
    func body(content: Content) -> some View {
        content.tint(SKIRRBrand.accent).accentColor(SKIRRBrand.accent)
            .preferredColorScheme(appearance == "dark" ? .dark : appearance == "light" ? .light : nil)
    }
}
